-- =============================================================================
-- V1__init.sql — Untangle initial schema
--
-- Conventions (see docs/database.md and ADRs 003, 008, 009, 010):
--   * Primary keys: UUIDv7 (time-ordered) generated by PostgreSQL 18's uuidv7().
--     The application also generates v7 ids itself, so the default is a fallback
--     for SQL-only inserts (seeds, manual fixes).
--   * Timestamps: timestamptz, always UTC.
--   * Enums: VARCHAR + CHECK (not PostgreSQL ENUM types) so values can be added
--     in a plain migration without ALTER TYPE locking issues.
--   * Mutable rows carry `version` for optimistic locking.
--   * Invariants that must never be violated are enforced HERE as constraints,
--     not only in Java: the database is the last line of defence.
-- =============================================================================

-- Trigram matching for ticket search (ILIKE '%refund%' can use a GIN index).
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- -----------------------------------------------------------------------------
-- agents: support staff, who are also the system's users
-- -----------------------------------------------------------------------------
CREATE TABLE agents (
    id                    uuid         PRIMARY KEY DEFAULT uuidv7(),
    full_name             varchar(120) NOT NULL,
    email                 varchar(254) NOT NULL,
    password_hash         varchar(100) NOT NULL,
    role                  varchar(10)  NOT NULL,
    active                boolean      NOT NULL DEFAULT true,
    failed_login_attempts integer      NOT NULL DEFAULT 0,
    locked_until          timestamptz,
    last_login_at         timestamptz,
    created_at            timestamptz  NOT NULL DEFAULT now(),
    updated_at            timestamptz  NOT NULL DEFAULT now(),
    version               bigint       NOT NULL DEFAULT 0,

    CONSTRAINT ck_agents_role            CHECK (role IN ('ADMIN', 'LEAD', 'AGENT')),
    CONSTRAINT ck_agents_full_name       CHECK (length(btrim(full_name)) >= 2),
    CONSTRAINT ck_agents_email_format    CHECK (email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
    CONSTRAINT ck_agents_failed_attempts CHECK (failed_login_attempts >= 0)
);

-- Emails are unique regardless of case: Rahul@x.com and rahul@x.com are one person.
CREATE UNIQUE INDEX ux_agents_email_lower ON agents (lower(email));

COMMENT ON TABLE agents IS 'Support staff (system users). Never hard-deleted; deactivated via active=false.';

-- -----------------------------------------------------------------------------
-- partners: external systems allowed to create tickets via signed webhooks
-- -----------------------------------------------------------------------------
CREATE TABLE partners (
    id                         uuid         PRIMARY KEY DEFAULT uuidv7(),
    code                       varchar(64)  NOT NULL,
    name                       varchar(120) NOT NULL,
    -- HMAC secrets must be recoverable to verify signatures, so they are
    -- encrypted (AES-256-GCM), never hashed. See ADR on partner secrets (Phase 4).
    secret_ciphertext          text         NOT NULL,
    previous_secret_ciphertext text,
    previous_secret_expires_at timestamptz,
    active                     boolean      NOT NULL DEFAULT true,
    rate_limit_per_minute      integer      NOT NULL DEFAULT 60,
    created_at                 timestamptz  NOT NULL DEFAULT now(),
    updated_at                 timestamptz  NOT NULL DEFAULT now(),
    version                    bigint       NOT NULL DEFAULT 0,

    CONSTRAINT uq_partners_code          UNIQUE (code),
    -- Codes travel in the X-Partner-Id header: lowercase slug only.
    CONSTRAINT ck_partners_code_format   CHECK (code ~ '^[a-z0-9][a-z0-9-]{1,62}[a-z0-9]$'),
    CONSTRAINT ck_partners_rate_limit    CHECK (rate_limit_per_minute BETWEEN 1 AND 10000),
    -- A previous secret only exists together with its expiry (rotation grace window).
    CONSTRAINT ck_partners_previous_secret
        CHECK ((previous_secret_ciphertext IS NULL) = (previous_secret_expires_at IS NULL))
);

-- -----------------------------------------------------------------------------
-- tickets: one row per customer complaint
-- -----------------------------------------------------------------------------
-- Human-readable numbers (UNT-000123) come from a sequence: gap-tolerant,
-- concurrency-safe, no "SELECT max()+1" race.
CREATE SEQUENCE ticket_number_seq AS bigint START WITH 1 INCREMENT BY 1;

-- Formats the next sequence value as UNT-000123. nextval() is called exactly once.
-- lpad never truncates: past 999999 the number simply grows (UNT-1000000).
CREATE FUNCTION next_ticket_number() RETURNS varchar
    LANGUAGE sql VOLATILE AS
$$
SELECT 'UNT-' || lpad(n::text, greatest(6, length(n::text)), '0')
FROM (SELECT nextval('ticket_number_seq') AS n) AS s
$$;

CREATE TABLE tickets (
    id                  uuid          PRIMARY KEY DEFAULT uuidv7(),
    ticket_number       varchar(20)   NOT NULL DEFAULT next_ticket_number(),
    subject             varchar(150)  NOT NULL,
    description         varchar(5000) NOT NULL,
    customer_name       varchar(120)  NOT NULL,
    customer_email      varchar(254),
    category            varchar(20)   NOT NULL,
    priority            varchar(10)   NOT NULL,
    status              varchar(15)   NOT NULL DEFAULT 'OPEN',
    assigned_agent_id   uuid          REFERENCES agents (id) ON DELETE RESTRICT,
    created_by_agent_id uuid          REFERENCES agents (id) ON DELETE RESTRICT,
    source              varchar(10)   NOT NULL,
    partner_id          uuid          REFERENCES partners (id) ON DELETE RESTRICT,
    external_event_id   varchar(128),
    escalation_level    smallint      NOT NULL DEFAULT 0,
    sla_due_at          timestamptz   NOT NULL,
    first_response_at   timestamptz,
    resolved_at         timestamptz,
    closed_at           timestamptz,
    reopened_count      integer       NOT NULL DEFAULT 0,
    created_at          timestamptz   NOT NULL DEFAULT now(),
    updated_at          timestamptz   NOT NULL DEFAULT now(),
    version             bigint        NOT NULL DEFAULT 0,

    CONSTRAINT uq_tickets_number       UNIQUE (ticket_number),
    -- Requirement 8: every ticket must have a valid priority. Case-sensitive on purpose.
    CONSTRAINT ck_tickets_priority     CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    CONSTRAINT ck_tickets_category     CHECK (category IN ('BILLING', 'TECHNICAL', 'ACCOUNT', 'REFUND', 'GENERAL', 'OTHER')),
    CONSTRAINT ck_tickets_status       CHECK (status IN ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED')),
    CONSTRAINT ck_tickets_source       CHECK (source IN ('MANUAL', 'WEBHOOK')),
    CONSTRAINT ck_tickets_subject      CHECK (length(btrim(subject)) >= 1),
    CONSTRAINT ck_tickets_description  CHECK (length(btrim(description)) >= 10),
    CONSTRAINT ck_tickets_customer     CHECK (length(btrim(customer_name)) >= 2),
    CONSTRAINT ck_tickets_counters     CHECK (escalation_level >= 0 AND reopened_count >= 0),
    -- Webhook tickets always know their partner and event id; manual tickets never do.
    CONSTRAINT ck_tickets_source_consistency
        CHECK ((source = 'WEBHOOK') = (external_event_id IS NOT NULL AND partner_id IS NOT NULL)),
    -- Manual tickets record who created them; webhook tickets have no human creator.
    CONSTRAINT ck_tickets_creator
        CHECK ((source = 'MANUAL') = (created_by_agent_id IS NOT NULL)),
    -- Lifecycle invariants (mirror TicketStateMachine; defence in depth).
    CONSTRAINT ck_tickets_closed_has_timestamp   CHECK (status <> 'CLOSED' OR closed_at IS NOT NULL),
    CONSTRAINT ck_tickets_resolved_has_timestamp CHECK (status <> 'RESOLVED' OR resolved_at IS NOT NULL),
    CONSTRAINT ck_tickets_in_progress_assigned   CHECK (status <> 'IN_PROGRESS' OR assigned_agent_id IS NOT NULL)
);

-- Requirement 8: a partner's event id can create at most one ticket, even under
-- 20 concurrent retries. The webhook relies on THIS index, not on check-then-insert.
CREATE UNIQUE INDEX ux_tickets_partner_event
    ON tickets (partner_id, external_event_id)
    WHERE external_event_id IS NOT NULL;

-- Dashboard breakdowns and the default list filter (status + priority).
CREATE INDEX ix_tickets_status_priority ON tickets (status, priority);
-- "My open tickets", workload per agent.
CREATE INDEX ix_tickets_assignee_status ON tickets (assigned_agent_id, status);
-- Default list sort (newest first) and created-vs-resolved trends.
CREATE INDEX ix_tickets_created_at      ON tickets (created_at DESC);
-- SLA scheduler: only unresolved tickets can breach, so the index stays small.
CREATE INDEX ix_tickets_sla_due_unresolved
    ON tickets (sla_due_at)
    WHERE status IN ('OPEN', 'IN_PROGRESS');
-- Free-text search (`q` filter) with ILIKE '%term%'.
CREATE INDEX ix_tickets_subject_trgm     ON tickets USING gin (subject gin_trgm_ops);
CREATE INDEX ix_tickets_description_trgm ON tickets USING gin (description gin_trgm_ops);

-- -----------------------------------------------------------------------------
-- ticket_comments: append-only timeline (comments, resolution notes, system events)
-- -----------------------------------------------------------------------------
CREATE TABLE ticket_comments (
    id              uuid          PRIMARY KEY DEFAULT uuidv7(),
    ticket_id       uuid          NOT NULL REFERENCES tickets (id) ON DELETE CASCADE,
    -- NULL = written by the system (e.g. SLA scheduler).
    author_agent_id uuid          REFERENCES agents (id) ON DELETE RESTRICT,
    type            varchar(20)   NOT NULL,
    body            varchar(5000) NOT NULL,
    metadata        jsonb,
    created_at      timestamptz   NOT NULL DEFAULT now(),

    CONSTRAINT ck_comments_type   CHECK (type IN ('COMMENT', 'RESOLUTION_NOTE', 'SYSTEM')),
    CONSTRAINT ck_comments_body   CHECK (length(btrim(body)) >= 1),
    -- People write comments and notes; only SYSTEM entries may be authorless.
    CONSTRAINT ck_comments_author CHECK (type = 'SYSTEM' OR author_agent_id IS NOT NULL)
);

CREATE INDEX ix_comments_ticket_created ON ticket_comments (ticket_id, created_at);

-- The timeline is an audit trail: rows can be added, never edited (ADR-010).
CREATE FUNCTION forbid_update() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    RAISE EXCEPTION 'Table % is append-only: UPDATE is not allowed', TG_TABLE_NAME
        USING ERRCODE = 'check_violation';
END;
$$;

CREATE TRIGGER trg_ticket_comments_append_only
    BEFORE UPDATE ON ticket_comments
    FOR EACH ROW EXECUTE FUNCTION forbid_update();

-- -----------------------------------------------------------------------------
-- webhook_deliveries: audit of every webhook attempt, accepted or rejected
-- -----------------------------------------------------------------------------
CREATE TABLE webhook_deliveries (
    id               uuid         PRIMARY KEY DEFAULT uuidv7(),
    -- NULL when the partner header was missing or unknown.
    partner_id       uuid         REFERENCES partners (id) ON DELETE RESTRICT,
    partner_code_raw varchar(128),
    event_id         varchar(128),
    received_at      timestamptz  NOT NULL DEFAULT now(),
    outcome          varchar(30)  NOT NULL,
    ticket_id        uuid         REFERENCES tickets (id) ON DELETE SET NULL,
    reason           varchar(500),
    source_ip        varchar(45),
    -- Fingerprint of the body; the raw payload is never stored (PII minimisation).
    payload_sha256   varchar(64),

    CONSTRAINT ck_deliveries_outcome CHECK (outcome IN (
        'CREATED', 'DUPLICATE', 'REJECTED_SIGNATURE', 'REJECTED_TIMESTAMP',
        'REJECTED_UNKNOWN_PARTNER', 'REJECTED_VALIDATION', 'REJECTED_TOO_LARGE', 'RATE_LIMITED')),
    CONSTRAINT ck_deliveries_ticket  CHECK (outcome NOT IN ('CREATED', 'DUPLICATE') OR ticket_id IS NOT NULL),
    CONSTRAINT ck_deliveries_sha256  CHECK (payload_sha256 IS NULL OR payload_sha256 ~ '^[0-9a-f]{64}$')
);

-- Admin "Webhook logs" screen (newest first, per partner) and the 30-day retention job.
CREATE INDEX ix_deliveries_received_at ON webhook_deliveries (received_at DESC);
CREATE INDEX ix_deliveries_partner     ON webhook_deliveries (partner_id, received_at DESC);

-- -----------------------------------------------------------------------------
-- refresh_tokens: hashed, rotated refresh tokens grouped into families
-- -----------------------------------------------------------------------------
CREATE TABLE refresh_tokens (
    id             uuid         PRIMARY KEY DEFAULT uuidv7(),
    agent_id       uuid         NOT NULL REFERENCES agents (id) ON DELETE RESTRICT,
    -- SHA-256 of the token; the token itself is never stored.
    token_hash     varchar(64)  NOT NULL,
    family_id      uuid         NOT NULL,
    expires_at     timestamptz  NOT NULL,
    revoked_at     timestamptz,
    replaced_by_id uuid         REFERENCES refresh_tokens (id) ON DELETE SET NULL,
    created_at     timestamptz  NOT NULL DEFAULT now(),
    user_agent     varchar(255),
    ip             varchar(45),
    version        bigint       NOT NULL DEFAULT 0,

    CONSTRAINT uq_refresh_tokens_hash   UNIQUE (token_hash),
    CONSTRAINT ck_refresh_tokens_hash   CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_refresh_tokens_expiry CHECK (expires_at > created_at)
);

-- Reuse detection revokes a whole family at once.
CREATE INDEX ix_refresh_tokens_family ON refresh_tokens (family_id);
-- Logout / deactivation revokes an agent's live tokens.
CREATE INDEX ix_refresh_tokens_agent_live ON refresh_tokens (agent_id) WHERE revoked_at IS NULL;

-- -----------------------------------------------------------------------------
-- notifications: in-app alerts (assignments, escalations, SLA breaches...)
-- -----------------------------------------------------------------------------
CREATE TABLE notifications (
    id                 uuid         PRIMARY KEY DEFAULT uuidv7(),
    recipient_agent_id uuid         NOT NULL REFERENCES agents (id) ON DELETE RESTRICT,
    type               varchar(20)  NOT NULL,
    ticket_id          uuid         NOT NULL REFERENCES tickets (id) ON DELETE CASCADE,
    message            varchar(500) NOT NULL,
    read_at            timestamptz,
    created_at         timestamptz  NOT NULL DEFAULT now(),

    CONSTRAINT ck_notifications_type CHECK (type IN ('ASSIGNED', 'ESCALATED', 'SLA_BREACH', 'MENTION', 'REOPENED'))
);

-- Notification drawer (newest first) and the unread badge count.
CREATE INDEX ix_notifications_recipient ON notifications (recipient_agent_id, created_at DESC);
CREATE INDEX ix_notifications_unread    ON notifications (recipient_agent_id) WHERE read_at IS NULL;

-- -----------------------------------------------------------------------------
-- ticket_ai_insights: AI suggestions with model/prompt provenance and feedback
-- -----------------------------------------------------------------------------
CREATE TABLE ticket_ai_insights (
    id                  uuid         PRIMARY KEY DEFAULT uuidv7(),
    -- NULL for triage run on the create form, before the ticket exists.
    ticket_id           uuid         REFERENCES tickets (id) ON DELETE CASCADE,
    kind                varchar(20)  NOT NULL,
    content             jsonb        NOT NULL,
    model               varchar(100) NOT NULL,
    prompt_version      varchar(20)  NOT NULL,
    accepted            boolean,
    -- NULL when generated by the system (webhook auto-triage).
    created_by_agent_id uuid         REFERENCES agents (id) ON DELETE RESTRICT,
    created_at          timestamptz  NOT NULL DEFAULT now(),
    version             bigint       NOT NULL DEFAULT 0,

    CONSTRAINT ck_ai_insights_kind   CHECK (kind IN ('TRIAGE', 'SUMMARY', 'REPLY_DRAFT')),
    CONSTRAINT ck_ai_insights_ticket CHECK (kind = 'TRIAGE' OR ticket_id IS NOT NULL)
);

CREATE INDEX ix_ai_insights_ticket ON ticket_ai_insights (ticket_id, kind, created_at DESC);

-- -----------------------------------------------------------------------------
-- shedlock: distributed lock so only one instance runs each scheduled job.
-- Schema as documented by ShedLock's JDBC provider (used from Phase 5).
-- -----------------------------------------------------------------------------
CREATE TABLE shedlock (
    name       varchar(64)  PRIMARY KEY,
    lock_until timestamptz  NOT NULL,
    locked_at  timestamptz  NOT NULL,
    locked_by  varchar(255) NOT NULL
);
